g script...","signature":""}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":318,"cache_read_input_tokens":57750,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":318},"output_tokens":8,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"73c3b854-fd2a-4cd9-baf1-2aece9e3a5f6","uuid":"866b4fb3-282b-4594-894c-6ae5006b3459"}
